   115	fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
   116	    if !path.starts_with(root) {
   117	        return Err(LocateError::OutsideWorkspaceRoot {
   118	            path: path.to_path_buf(),
   119	            root: root.to_path_buf(),
   120	        });
   121	    }
   122	    let rel = path.strip_prefix(root).unwrap();
   123	    if rel.as_os_str().is_empty() {
   124	        Ok(PathBuf::from("."))
   125	    } else {
   126	        workspace_relative(rel).map_err(|_e| LocateError::OutsideWorkspaceRoot {
   127	            path: path.to_path_buf(),
   128	            root: root.to_path_buf(),
   129	        })
   130	    }
