    35	impl ProjectLocator for IgnoreWalkLocator {
    36	    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
    37	        let mut results = Vec::new();
    38	        let cargo_membership = membership::read_cargo_membership(&self.root);
    39	        let npm_membership = membership::read_npm_membership(&self.root);
    40	        let python_membership = membership::read_python_membership(&self.root);
    41	        let walker = WalkBuilder::new(&self.root)
    42	            .hidden(true)
    43	            .git_ignore(true)
    44	            .parents(false)
    45	            .max_depth(Some(32))
    46	            // Symlinked package directories (e.g. vendor-link style monorepos) are a
    47	            // supported workspace pattern -- discovery follows them deliberately. The
    48	            // existing max_depth(32) cap already bounds a symlink cycle from hanging.
    49	            .follow_links(true)
    50	            .filter_entry({
    51	                let skip = self.skip.clone();
    52	                move |entry| {
    53	                    if let Some(name) = entry.file_name().to_str() {
    54	                        if skip.contains(name) {
    55	                            return false;
    56	                        }
    57	                    }
    58	                    true
    59	                }
    60	            })
    61	            .build();
    62	
    63	        for entry_res in walker {
    64	            let entry = entry_res.map_err(|e| LocateError::Walk {
    65	                path: self.root.clone(),
    66	                message: e.to_string(),
    67	            })?;
    68	
    69	            let path = entry.path();
    70	            if !path.is_dir() {
    71	                continue;
    72	            }
    73	
    74	            for ecosystem in Ecosystem::CANONICAL {
    75	                // Every `Ecosystem::CANONICAL` member has a canonical
    76	                // manifest format by construction -- see its doc comment.
    77	                let format = ecosystem
    78	                    .canonical_manifest_format()
    79	                    .expect("CANONICAL ecosystems always have a canonical manifest format");
    80	                let manifest_path = path.join(format.file_name());
    81	                let Ok(content) = fs::read_to_string(&manifest_path) else {
    82	                    continue;
    83	                };
    84	                let Ok(identity) = callisto_manifests::read_identity(format, &content, &manifest_path) else {
    85	                    continue;
    86	                };
    87	                let Some(name) = identity.name else {
    88	                    continue;
    89	                };
    90	
    91	                let rel = to_workspace_relative(path, &self.root)?;
    92	                let is_root = rel == Path::new(".");
    93	                let admitted = match ecosystem {
    94	                    Ecosystem::Cargo => cargo_membership.admits(&rel, is_root),
    95	                    Ecosystem::Npm => npm_membership.admits(&rel, is_root),
    96	                    Ecosystem::Pypi => python_membership.admits(&rel, is_root),
    97	                    _ => false,
    98	                };
    99	                if admitted {
   100	                    let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
   101	                    results.push(ProjectRoot {
   102	                        id,
   103	                        path: rel,
   104	                        ecosystem,
   105	                    });
   106	                }
   107	            }
   108	        }
   109	
   110	        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
   111	        Ok(results)
   112	    }
   113	}
