    18	/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
    19	/// against `package`'s name.
    20	///
    21	/// This is the single derivation of release package identity shared by every
    22	/// site that computes or verifies release authority: [`derive_release_decision`],
    23	/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
    24	/// Per this module's own established lesson (see the doc comment on
    25	/// [`derive_release_commit_decision`]), independently reimplementing this
    26	/// mapping at each call site is exactly the kind of duplicated derivation
    27	/// that drifts -- so it lives here once instead.
    28	pub(crate) fn release_package_ids(package: &Package) -> Result<Vec<ReleasePackageId>, GraphError> {
    29	    package
    30	        .canonical_manifests()
    31	        .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
    32	        .collect::<Result<Vec<_>, _>>()
    33	        .map_err(GraphError::from)
    34	}
