    75	/// Derives a durable decision for explicit, exact release identities.
    76	///
    77	/// A linked group is one release unit: selecting any member includes every
    78	/// member of that linked group which the version plan selected. All other
    79	/// packages remain outside the authority boundary. The caller must pass
    80	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
    81	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
    82	/// for release authority.
    83	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    84	    workspace: &Workspace<'_, R, D>,
    85	    plan: &VersionPlan,
    86	    selections: &[ReleasePackageId],
    87	) -> Result<ReleaseDecisionV1, GraphError> {
    88	    let complete = derive_release_decision(workspace, plan)?;
    89	
    90	    let mut seen = std::collections::BTreeSet::new();
    91	    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
    92	        return Err(GraphError::ReleaseSelectionInvalid {
    93	            package: duplicate.clone(),
    94	            reason: ReleaseSelectionInvalidReason::Duplicate,
    95	        });
    96	    }
    97	
    98	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    99	    for selection in &selected {
   100	        if !complete.entries.iter().any(|entry| &entry.package == *selection) {
   101	            return Err(GraphError::ReleaseSelectionInvalid {
   102	                package: (*selection).clone(),
   103	                reason: ReleaseSelectionInvalidReason::NotInPlan,
   104	            });
   105	        }
   106	    }
   107	
   108	    let linked_groups = complete
   109	        .entries
   110	        .iter()
   111	        .filter(|entry| selected.contains(&entry.package))
   112	        .flat_map(|entry| entry.reasons.iter())
   113	        .filter_map(|reason| match reason {
   114	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
   115	            _ => None,
   116	        })
   117	        .collect::<std::collections::BTreeSet<_>>();
   118	
   119	    let entries = complete
   120	        .entries
   121	        .into_iter()
   122	        .filter(|entry| {
   123	            selected.contains(&entry.package)
   124	                || entry.reasons.iter().any(|reason| {
   125	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
   126	                })
   127	        })
   128	        .collect();
   129	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
   130	}
