    16	impl IgnoreWalkLocator {
    17	    pub fn new(root: &Path) -> Self {
    18	        let mut skip = BTreeSet::new();
    19	        skip.insert("target");
    20	        skip.insert("node_modules");
    21	        skip.insert(".git");
    22	        skip.insert(".moon");
    23	        skip.insert("dist");
    24	
    25	        let canonical = dunce::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
    26	        IgnoreWalkLocator { root: canonical, skip }
    27	    }
    28	
    29	    pub fn discover(start: &Path) -> Result<Self, LocateError> {
    30	        let root = find_workspace_root(start)?;
    31	        Ok(Self::new(&root))
    32	    }
    33	}
