    36	/// Derives the durable roster from a freshly computed version plan.
    37	///
    38	/// The caller supplies the plan from the same workspace observation; this
    39	/// function never inspects `PublishPlan` or a caller-provided release roster.
    40	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    41	    workspace: &Workspace<'_, R, D>,
    42	    plan: &VersionPlan,
    43	) -> Result<ReleaseDecisionV1, GraphError> {
    44	    let mut package_ids = std::collections::BTreeMap::new();
    45	    for package in workspace.graph.packages() {
    46	        let ids = release_package_ids(package)?;
    47	        package_ids.insert(package.id.clone(), ids);
    48	    }
    49	
    50	    let mut entries = Vec::new();
    51	    for bump in &plan.bumps {
    52	        // `plan` is contractually derived from this same workspace
    53	        // observation (see doc comment above), so every bump's package must
    54	        // already be a key here -- a miss means the plan/workspace pairing
    55	        // itself is inconsistent, not a recoverable operator condition.
    56	        let ids = package_ids
    57	            .get(&bump.package)
    58	            .ok_or_else(|| GraphError::ReleaseInvariant {
    59	                detail: format!(
    60	                    "version plan references package `{}`, which is absent from this workspace observation",
    61	                    bump.package.display_name()
    62	                ),
    63	            })?;
    64	        for id in ids {
    65	            entries.push(ReleaseDecisionEntry {
    66	                package: id.clone(),
    67	                target_version: bump.to.clone(),
    68	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
    69	            });
    70	        }
    71	    }
    72	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
    73	}
