   338	impl ValidatedReleaseIntent<'_> {
   339	    /// Dispatches exactly one graph-private operation prepared during fresh
   340	    /// validation. This is intentionally the only production effect path: it
   341	    /// never accepts a path, endpoint, tag, package name, or version from a
   342	    /// caller.
   343	    pub(crate) fn dispatch_prepared(
   344	        &self,
   345	        permit: &ApplyPermit,
   346	        id: &ReleaseOperationId,
   347	    ) -> Result<OperationOutcome, GraphError> {
   348	        let operation = self
   349	            .prepared
   350	            .operations
   351	            .get(id)
   352	            .ok_or_else(|| GraphError::ReleaseInvariant {
   353	                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
   354	            })?;
   355	        match operation {
   356	            PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
   357	            PreparedOperation::Tag {
   358	                name,
   359	                target,
   360	                annotation,
   361	            } => self.dispatch_tag(permit, name, target, annotation),
   362	            PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(tag),
   363	        }
   364	    }
   365	
   366	    fn dispatch_registry(
   367	        &self,
   368	        _permit: &ApplyPermit,
   369	        id: &ReleaseOperationId,
   370	        prepared: &PreparedOperation,
   371	    ) -> Result<OperationOutcome, GraphError> {
   372	        let PreparedOperation::RegistryPublish {
   373	            package_dir,
   374	            package_name,
   375	            version,
   376	            registry,
   377	            npm_access,
   378	            npm_tag,
   379	        } = prepared
   380	        else {
    36	/// Derives the durable roster from a freshly computed version plan.
    37	///
    38	/// The caller supplies the plan from the same workspace observation; this
    39	/// function never inspects `PublishPlan` or a caller-provided release roster.
    40	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    41	    workspace: &Workspace<'_, R, D>,
    42	    plan: &VersionPlan,
    43	) -> Result<ReleaseDecisionV1, GraphError> {
    44	    let mut package_ids = std::collections::BTreeMap::new();
    45	    for package in workspace.graph.packages() {
    46	        let ids = release_package_ids(package)?;
    47	        package_ids.insert(package.id.clone(), ids);
    48	    }
    49	
    50	    let mut entries = Vec::new();
    51	    for bump in &plan.bumps {
    52	        // `plan` is contractually derived from this same workspace
    53	        // observation (see doc comment above), so every bump's package must
    54	        // already be a key here -- a miss means the plan/workspace pairing
    55	        // itself is inconsistent, not a recoverable operator condition.
    56	        let ids = package_ids
    57	            .get(&bump.package)
    58	            .ok_or_else(|| GraphError::ReleaseInvariant {
    59	                detail: format!(
    60	                    "version plan references package `{}`, which is absent from this workspace observation",
    61	                    bump.package.display_name()
    62	                ),
    63	            })?;
    64	        for id in ids {
    65	            entries.push(ReleaseDecisionEntry {
    66	                package: id.clone(),
    67	                target_version: bump.to.clone(),
    68	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
    69	            });
    70	        }
    71	    }
    72	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
    73	}
