385	/// File-absent, field-absent, non-array "workspaces", and non-string array
386	/// entries all safely fall back to `None` (a plain `?`-chain), which causes
387	/// `read_npm_membership` to admit-all.
388	fn read_package_json_workspaces(root: &Path) -> Option<Vec<String>> {
389	    let content = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())).ok()?;
390	    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
390	    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
391	    let field = val.get("workspaces")?;
392	    let arr = field.as_array()?;
393	    let mut out = Vec::with_capacity(arr.len());
394	    for v in arr {
395	        out.push(v.as_str()?.to_string());
396	    }
397	    Some(out)
398	}
