 75	/// Workspace-membership filter shared by Cargo's `[workspace]` and uv's
 76	/// `[tool.uv.workspace]` -- both use the identical members/exclude
 77	/// glob-array shape, including a root manifest that is itself both a
 78	/// package/project and a workspace root (hybrid root). `NpmMembership`
 79	/// deliberately does NOT go through this type: npm's shape genuinely
 80	/// differs (JSON not TOML, no `exclude` concept, and a pnpm-workspace.yaml
 81	/// fallback with its own precedence rules).
 82	pub(crate) struct Membership {
 83	    members: Option<NegatableGlobSet>,
 84	    exclude: NegatableGlobSet,
 85	    hybrid_root: bool,
 86	}
 87	
 88	impl Membership {
 89	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
 90	    /// `is_root` is true exactly when `rel == Path::new(".")`.
 91	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
 92	        if is_root && self.hybrid_root {
 93	            return true;
 94	        }
 95	        if self.exclude.is_match(rel) {
 96	            return false;
 97	        }
 98	        match &self.members {
 99	            None => true,
100	            Some(members) => members.is_match(rel),
101	        }
102	    }
103	
104	    fn absent() -> Self {
105	        Membership {
106	            members: None,
107	            exclude: NegatableGlobSet::empty(),
108	            hybrid_root: false,
109	        }
110	    }
111	}
112	
113	/// Safely parses a TOML array-of-strings item, returning `None` for any
114	/// other shape (bare string, table, non-string entries, etc.) instead of
115	/// panicking.
116	fn parse_toml_string_array(item: &toml_edit::Item) -> Option<Vec<String>> {
117	    let arr = item.as_array()?;
118	    let mut out = Vec::with_capacity(arr.len());
119	    for v in arr.iter() {
120	        out.push(v.as_str()?.to_string());
121	    }
122	    Some(out)
123	}
