322	pub(crate) struct NpmMembership {
323	    globs: Option<NegatableGlobSet>,
324	    hybrid_root: bool,
325	}
326	
327	impl NpmMembership {
328	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
329	    /// `is_root` is true exactly when `rel == Path::new(".")`.
330	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
331	        if is_root && self.hybrid_root {
332	            return true;
333	        }
334	        match &self.globs {
335	            None => true,
336	            Some(globs) => globs.is_match(rel),
337	        }
338	    }
339	}
